window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-42d6ae9a9a0485b2"]={"versions": [{"id": "FIG-42d6ae9a9a0485b2", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Mappings von Record Layouts auf Datentypen im Rahmen des AUTOSAR Software Component Templates. Das Diagramm modelliert einen Transformationsalgorithmus innerhalb einer iterativen Expansionsregion (<code>iterative</code> bzw. <code>for all newly required types</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Eingangs-Aktivitätsparameterknoten (ActivityParameterNode, links): <code>CalprmElementPrototype</code> und <code>SwRecordLayouts</code>.\n</li><li>Aktionen (Action / CallBehaviorAction):\n<ul class=\"fig-list\"><li><code>remember Name</code> (Aktion zur Zwischenspeicherung des Namens)\n</li><li><code>Get Descendant Groups/Values</code> (Aktion zur Extraktion von Kindgruppen bzw. -werten)\n</li><li><code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> (Aktion zur Namensbildung anhand von Ahnenknoten und Gruppenindex)\n</li><li><code>Create Type</code> (CallBehaviorAction, gekennzeichnet durch das Verschachtelungs-/Subaktivitätssymbol in der unteren rechten Ecke)\n</li></ul>\n</li><li>Kontrollknoten: Ein Synchronisationsbalken (Join-Node / Fork-Node) zur Zusammenführung der Steuerungs- bzw. Datenflüsse vor <code>Create Type</code>.\n</li><li>Ausgangs-Aktivitätsparameterknoten (ActivityParameterNode, rechts): <code>Data Type from Record layout</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Iterationsschleife durchläuft die Verarbeitung für alle neu benötigten Typen (<code>for all newly required types</code>).\n</li><li>Parallel bzw. zweigeteilt treffen die Eingangsdaten ein:\n<ul class=\"fig-list\"><li><code>CalprmElementPrototype</code> wird an die Aktion <code>remember Name</code> übergeben; das Resultat wird zur Join-Node geführt.\n</li><li><code>SwRecordLayouts</code> wird übergeben an <code>Get Descendant Groups/Values</code>, deren Ergebnis an <code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> weitergeleitet und anschließend ebenfalls in die Join-Node eingespeist wird.\n</li></ul>\n</li><li>Nach Synchronisation beider Pfade an der Join-Node wird die Aktivität <code>Create Type</code> angestoßen.\n</li><li>Das erzeugte Typ-Artefakt wird an den Ausgangsknoten <code>Data Type from Record layout</code> übergeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Algorithmus definiert das deterministische Vorgehen zur Ableitung von Datentypen aus Record Layouts für Kalibrierparameter-Prototypen (<code>CalprmElementPrototype</code>). Werkzeuge zur AUTOSAR-Modellgenerierung müssen sicherstellen, dass die Namenskonvention (<code>setRlDataTypeName by ancestor -&gt; GroupIndex</code>) sowie die Identifikation anhand des Prototypnamens eingehalten werden, um konsistente Datentypen aus den hierarchischen Record-Layout-Gruppen abzuleiten.</p>"}, {"id": "FIG-aad77288d886e155", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Mappings von Record Layouts auf Datentypen im Rahmen des AUTOSAR Software Component Templates. Das Diagramm modelliert einen Transformationsalgorithmus innerhalb einer iterativen Expansionsregion («iterative» bzw. <code>for all newly required types</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Eingangs-Aktivitätsparameterknoten (ActivityParameterNode, links): <code>CalprmElementPrototype</code> und <code>SwRecordLayouts</code>.\n</li><li>Aktionen (Action / CallBehaviorAction):\n<ul class=\"fig-list\"><li><code>remember Name</code> (Aktion zur Zwischenspeicherung des Namens)\n</li><li><code>Get Descendant Groups/Values</code> (Aktion zur Extraktion von Kindgruppen bzw. -werten)\n</li><li><code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> (Aktion zur Namensbildung anhand von Ahnenknoten und Gruppenindex)\n</li><li><code>Create Type</code> (CallBehaviorAction, gekennzeichnet durch das Verschachtelungs-/Subaktivitätssymbol in der unteren rechten Ecke)\n</li></ul>\n</li><li>Kontrollknoten: Ein Synchronisationsbalken (Join-Node / Fork-Node) zur Zusammenführung der Steuerungs- bzw. Datenflüsse vor <code>Create Type</code>.\n</li><li>Ausgangs-Aktivitätsparameterknoten (ActivityParameterNode, rechts): <code>Data Type from Record layout</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Iterationsschleife durchläuft die Verarbeitung für alle neu benötigten Typen (<code>for all newly required types</code>).\n</li><li>Parallel bzw. zweigeteilt treffen die Eingangsdaten ein:\n<ul class=\"fig-list\"><li><code>CalprmElementPrototype</code> wird an die Aktion <code>remember Name</code> übergeben; das Resultat wird zur Join-Node geführt.\n</li><li><code>SwRecordLayouts</code> wird übergeben an <code>Get Descendant Groups/Values</code>, deren Ergebnis an <code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> weitergeleitet und anschließend ebenfalls in die Join-Node eingespeist wird.\n</li></ul>\n</li><li>Nach Synchronisation beider Pfade an der Join-Node wird die Aktivität <code>Create Type</code> angestoßen.\n</li><li>Das erzeugte Typ-Artefakt wird an den Ausgangsknoten <code>Data Type from Record layout</code> übergeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Algorithmus definiert das deterministische Vorgehen zur Ableitung von Datentypen aus Record Layouts für Kalibrierparameter-Prototypen (<code>CalprmElementPrototype</code>). Werkzeuge zur AUTOSAR-Modellgenerierung müssen sicherstellen, dass die Namenskonvention (<code>setRlDataTypeName by ancestor -&gt; GroupIndex</code>) sowie die Identifikation anhand des Prototypnamens eingehalten werden, um konsistente Datentypen aus den hierarchischen Record-Layout-Gruppen abzuleiten.</p>"}, {"id": "FIG-905ab21352b183ff", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation der Ableitung von Datentypinhalten aus Record Layouts im Kontext der Datentypmodellierung des AUTOSAR Software Component Templates. Der Ablauf ist als iterative Region (<code>«iterative»</code>, Schleifenkopf <code>for all ApplicationDataTypes</code>) formuliert.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Eingangs-Aktivitätsparameterknoten (ActivityParameterNode, links): <code>ApplicationDataType</code>.\n</li><li>Aktionen (Action):\n<ul class=\"fig-list\"><li><code>CreateType</code> (Aktion zur Typerstellung)\n</li><li><code>create subElement</code> (Aktion zur Erstellung von Unterelementen)\n</li></ul>\n</li><li>Objektknoten (CentralBufferNode / ObjectNode):\n<ul class=\"fig-list\"><li><code>ImplementationDataTypeElement</code> (rechteckiger Datenknoten)\n</li></ul>\n</li><li>Ausgangs-Aktivitätsparameterknoten (ActivityParameterNode, rechts): <code>TypeContentFromRecordLayout</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Iteration erfolgt über alle <code>ApplicationDataType</code>-Elemente.\n</li><li>Der eingehende <code>ApplicationDataType</code> wird der Aktion <code>CreateType</code> zugeführt.\n</li><li>Nach Ausführung von <code>CreateType</code> wird die Aktion <code>create subElement</code> aufgerufen.\n</li><li><code>create subElement</code> erzeugt ein <code>ImplementationDataTypeElement</code>.\n</li><li>Das resultierende <code>ImplementationDataTypeElement</code> wird als <code>TypeContentFromRecordLayout</code> über den Ausgabeknoten bereitgestellt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Ablauf beschreibt die Transformation auf Basis von <code>ApplicationDataType</code> zu <code>ImplementationDataTypeElement</code> zur Befüllung des Inhalts aus Record Layouts (<code>TypeContentFromRecordLayout</code>). Implementierende Generatoren müssen die sequentielle Erzeugung der Datentypen und ihrer Sub-Elemente berücksichtigen, um eine valide Konvertierung zwischen Anwendungs- und Implementierungsdatentypen unter Berücksichtigung von Record Layouts sicherzustellen.</p>"}, {"id": "FIG-190e8aa48f3dd707", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Aktivitätsdiagramm zur Spezifikation des Mappings von Record Layouts auf Datentypen im Rahmen des AUTOSAR Software Component Templates. Das Diagramm modelliert einen Transformationsalgorithmus innerhalb einer iterativen Expansionsregion («iterative» bzw. <code>for all newly required types</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li>Eingangs-Aktivitätsparameterknoten (ActivityParameterNode, links): <code>CalprmElementPrototype</code> und <code>SwRecordLayouts</code>.\n</li><li>Aktionen (Action / CallBehaviorAction):\n<ul class=\"fig-list\"><li><code>remember Name</code> (Aktion zur Zwischenspeicherung des Namens)\n</li><li><code>Get Descendant Groups/Values</code> (Aktion zur Extraktion von Kindgruppen bzw. -werten)\n</li><li><code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> (Aktion zur Namensbildung anhand von Ahnenknoten und Gruppenindex)\n</li><li><code>Create Type</code> (CallBehaviorAction mit Verknüpfungssymbol)\n</li></ul>\n</li><li>Kontrollknoten: Join-Node zur Zusammenführung der Teilabläufe.\n</li><li>Ausgangs-Aktivitätsparameterknoten (ActivityParameterNode, rechts): <code>Data Type from Record layout</code> (im Bild als <code>Data T...</code> beschriftet).\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Die Iterationsschleife durchläuft die Verarbeitung für alle neu benötigten Typen (<code>for all newly required types</code>).\n</li><li>Parallel bzw. zweigeteilt treffen die Eingangsdaten ein:\n<ul class=\"fig-list\"><li><code>CalprmElementPrototype</code> wird an die Aktion <code>remember Name</code> übergeben; das Resultat wird zur Join-Node geführt.\n</li><li><code>SwRecordLayouts</code> wird übergeben an <code>Get Descendant Groups/Values</code>, deren Ergebnis an <code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> weitergeleitet und anschließend ebenfalls in die Join-Node eingespeist wird.\n</li></ul>\n</li><li>Nach Synchronisation beider Pfade an der Join-Node wird die Aktivität <code>Create Type</code> angestoßen.\n</li><li>Das erzeugte Typ-Artefakt wird an den Ausgangsknoten <code>Data Type from Record layout</code> übergeben.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Der Algorithmus definiert das deterministische Vorgehen zur Ableitung von Datentypen aus Record Layouts für Kalibrierparameter-Prototypen (<code>CalprmElementPrototype</code>). Werkzeuge zur AUTOSAR-Modellgenerierung müssen sicherstellen, dass die Namenskonvention (<code>setRlDataTypeName by ancestor -&gt; GroupIndex</code>) sowie die Identifikation anhand des Prototypnamens eingehalten werden, um konsistente Datentypen aus den hierarchischen Record-Layout-Gruppen abzuleiten.</p>"}], "trans": [{"from": "FIG-42d6ae9a9a0485b2", "to": "FIG-aad77288d886e155", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Die Schreibweise des Stereotyps oben links wurde von <code>iterative</code> zu <code>«iterative»</code> mit Guillemets korrigiert.\n</li><li>Die Trennschärfe, Skalierung und Kantenglättung des Aktivitätsdiagramms wurden redaktionell überarbeitet.\n</li></ul>"}, {"from": "FIG-aad77288d886e155", "to": "FIG-905ab21352b183ff", "fr": "R3.0.7", "tr": "R3.1.5", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Der Schleifenkopf der iterativen Region wurde von <code>for all newly required types</code> auf <code>for all ApplicationDataTypes</code> geändert.\n</li><li>Die beiden Eingangsparameterknoten <code>CalprmElementPrototype</code> und <code>SwRecordLayouts</code> wurden durch einen einzelnen Eingangsknoten <code>ApplicationDataType</code> ersetzt.\n</li><li>Die Aktionen <code>remember Name</code>, <code>Get Descendant Groups/Values</code> und <code>setRlDataTypeName by ancestor -&gt; GroupIndex</code> sowie die Join-Node (Synchronisationsbalken) entfallen vollständig.\n</li><li>Neu hinzugefügt wurden die Aktionen <code>CreateType</code> und nachgelagert <code>create subElement</code>.\n</li><li>Ein neuer Objektknoten <code>ImplementationDataTypeElement</code> nimmt das Zwischenergebnis von <code>create subElement</code> auf.\n</li><li>Der Ausgangsparameterknoten wurde von <code>Data Type from Record layout</code> (bzw. abgeschnittenes Label) in <code>TypeContentFromRecordLayout</code> umbenannt und wird nun direkt aus <code>ImplementationDataTypeElement</code> gespeist.\n</li></ul>"}, {"from": "FIG-905ab21352b183ff", "to": "FIG-190e8aa48f3dd707", "fr": "R3.1.5", "tr": "R3.2.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Der Schleifenkopf der iterativen Region wurde von <code>for all ApplicationDataTypes</code> zurück auf <code>for all newly required types</code> geändert.\n</li><li>Der Eingangsknoten <code>ApplicationDataType</code> wurde wieder durch die zwei Eingangsparameterknoten <code>CalprmElementPrototype</code> und <code>SwRecordLayouts</code> ersetzt.\n</li><li>Die Aktionen <code>CreateType</code>, <code>create subElement</code> und der Objektknoten <code>ImplementationDataTypeElement</code> wurden entfernt.\n</li><li>Wiederhergestellt wurden die Aktionen <code>remember Name</code>, <code>Get Descendant Groups/Values</code>, <code>setRlDataTypeName by ancestor -&gt; GroupIndex</code>, die Join-Node sowie die aufgerufene Aktivität <code>Create Type</code> (mit Verknüpfungssymbol).\n</li><li>Der Ausgangsparameterknoten liefert anstelle von <code>TypeContentFromRecordLayout</code> wieder <code>Data Type from Record layout</code> (im Bild als <code>Data T...</code> dargestellt).\n</li></ul>"}]};
